1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { SftpServer } from "../lib/sftp";
4	import { withServerSsh, exec, SETUP_TIMEOUT_MS } from "../lib/ssh-exec";
5	import {
6	  controlSpec,
7	  isGameFamily,
8	  isPowerAction,
9	  remoteLocateDir,
10	  runRcon,
11	  parsePlayers,
12	  computeNextRun,
13	  computeNextIntervalRun,
14	  shq,
15	  isSafeRemotePath,
16	  GAME_BACKUP_DIR,
17	  type GameControlSpec,
18	} from "../lib/game-control";
19	import type { Job } from "@prisma/client";
20	
21	/**
22	 * Game server control-panel worker handlers.
23	 *
24	 * Registered in worker/index.ts:
25	 *   GAME_POWER:  gamePower,
26	 *   GAME_BACKUP: gameBackup,
27	 * and `gameScheduleSweep()` called on a ~60s timer.
28	 *
29	 * Everything runs over the platform's existing SSH (lib/ssh-exec withServerSsh —
30	 * host/port/root-password derived exactly like lib/sftp). Family/unit/path values
31	 * that reach the shell are compile-time constants or allowlisted (lib/game-control),
32	 * and the root password is never surfaced in an error (only a trimmed remote stderr
33	 * is, which never contains it).
34	 *
35	 * SANDBOX / no VM: handlers notify a simulation and touch nothing.
36	 */
37	
38	const CONTROL_FIELDS = {
39	  id: true,
40	  userId: true,
41	  hostname: true,
42	  status: true,
43	  rootPassword: true,
44	  rootPasswordEnc: true,
45	  sshPort: true,
46	  dedicatedIp: { select: { address: true } },
47	  node: { select: { publicIp: true } },
48	  osTemplate: { select: { family: true } },
49	  gamePlan: { select: { gameFamily: true } },
50	} as const;
51	
52	type ControlServer = {
53	  id: string;
54	  userId: string;
55	  hostname: string;
56	  status: string;
57	  rootPassword: string | null;
58	  rootPasswordEnc: string | null;
59	  sshPort: number | null;
60	  dedicatedIp: { address: string } | null;
61	  node: { publicIp: string } | null;
62	  osTemplate: { family: string | null };
63	  gamePlan: { gameFamily: string | null } | null;
64	};
65	
66	async function notify(userId: string, title: string, body?: string, href?: string) {
67	  try {
68	    await db.notification.create({ data: { userId, title, body, href } });
69	  } catch (e) {
70	    console.error("[game-control] notify failed", e);
71	  }
72	}
73	
74	function resolveSpec(server: ControlServer): GameControlSpec {
75	  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
76	  if (!isGameFamily(fam)) throw new Error("not a game server");
77	  const spec = controlSpec(fam);
78	  if (!spec) throw new Error("no control spec for family");
79	  return spec;
80	}
81	
82	/**
83	 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
84	 * the family's control spec (compile-time constants); `action` is one of the three
85	 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
86	 * a successful action (the same discipline as worker/game-update.ts).
87	 */
88	function powerScript(spec: GameControlSpec, action: string): string {
89	  const hints = spec.serviceHints.map(shq).join(" ");
90	  return [
91	    `unit=""`,
92	    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
93	    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
94	    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
95	    `echo "NXGP:UNIT:$unit"`,
96	    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
97	    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
98	    `echo "NXGP:END"`,
99	  ].join("\n");
100	}
