102	/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
103	export async function gamePower(job: Job): Promise<void> {
104	  if (!job.serverId) throw new Error("game power: missing serverId");
105	  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
106	  if (!server) throw new Error(`Server ${job.serverId} not found`);
107	  const spec = resolveSpec(server);
108	
109	  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
110	  const action = String(p.action ?? "");
111	  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
112	  const href = `/dashboard/servers/${server.id}?tab=manage`;
113	
114	  if (SANDBOX) {
115	    await notify(
116	      server.userId,
117	      `Game service ${action} (sandbox) on ${server.hostname}`,
118	      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
119	      href
120	    );
121	    return;
122	  }
123	  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");
124	
125	  // Optional pre-restart announce over RCON (best-effort; never fails the action).
126	  if (action === "restart" && p.announce && spec.rcon === "source") {
127	    try {
128	      await withServerSsh(server as SftpServer, (conn) =>
129	        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
130	      );
131	    } catch (e) {
132	      console.error("[game-control] restart announce failed (continuing)", e);
133	    }
134	  }
135	
136	  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, powerScript(spec, action), SETUP_TIMEOUT_MS));
137	  const text = out.stdout;
138	  if (/NXGP:UNIT:NONE/.test(text)) {
139	    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `No game service unit was found on ${server.hostname}.`, href);
140	    throw new Error("game power: no service unit found");
141	  }
142	  const rc = Number(/NXGP:RC:(-?\d+)/.exec(text)?.[1] ?? "1");
143	  const state = /NXGP:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
144	  if (!/NXGP:END/.test(text) || rc !== 0) {
145	    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `The ${action} did not complete on ${server.hostname} (state: ${state}).`, href);
146	    throw new Error(`game power: ${action} failed rc=${rc} state=${state}`);
147	  }
148	  await notify(
149	    server.userId,
150	    `${spec.label} service ${action}ed on ${server.hostname}`,
151	    action === "stop" ? "The game service was stopped." : `The game service was ${action}ed (now ${state}).`,
152	    href
153	  );
154	
155	  // Persist the real systemd state so the dashboard's status dot can reflect
156	  // it. GAME_POWER only ever touches the game SERVICE inside the VM, never
157	  // `Server.status` (the VM's own power state) — those are genuinely
158	  // different things, but the panel's "Online/Offline" label was reading
159	  // `Server.status` alone, so a customer who stopped just their game service
160	  // (VM still up) kept seeing "Online" no matter what they did. Found live
161	  // 2026-09-09 via a real customer confused why "Status: Online" never
162	  // changed after repeated stop/start attempts. `_serviceState` follows the
163	  // same gameConfig-internal-marker convention as `_real`/`_realOk`/
164	  // `_appliedAt` elsewhere in this file's siblings — no schema migration
165	  // needed for what's fundamentally transient, best-effort runtime state.
166	  try {
167	    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
168	    const gameConfig = { ...(fresh?.gameConfig as Record<string, unknown> | null ?? {}), _serviceState: state };
169	    await db.server.update({ where: { id: server.id }, data: { gameConfig } });
170	  } catch (e) {
171	    console.error(`[game-control] could not persist _serviceState for ${server.hostname}`, e);
172	  }
173	}
