175	/** GAME_BACKUP — archive the world/save dir into a downloadable .tar.gz. */
176	export async function gameBackup(job: Job): Promise<void> {
177	  if (!job.serverId) throw new Error("game backup: missing serverId");
178	  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
179	  if (!server) throw new Error(`Server ${job.serverId} not found`);
180	  const spec = resolveSpec(server);
181	  const href = `/dashboard/servers/${server.id}?tab=manage`;
182	
183	  if (SANDBOX) {
184	    await notify(server.userId, `World backup created (sandbox) on ${server.hostname}`, `Sandbox only — no VM was contacted for the ${spec.label} world backup.`, href);
185	    return;
186	  }
187	  if (server.status !== "RUNNING") throw new Error("game backup: VM is not running");
188	
189	  const outcome = await withServerSsh(server as SftpServer, async (conn) => {
190	    const dir = await remoteLocateDir(conn, spec.dataRoots);
191	    if (!dir || !isSafeRemotePath(dir)) return { ok: false, msg: "Could not locate the world/save directory." };
192	    // Timestamped archive under the fixed backup dir. `parent`/`base` are derived
193	    // from the located (allowlisted) dir; every value interpolated is single-quoted.
194	    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
195	    const archive = `${GAME_BACKUP_DIR}/${spec.family}-${ts}.tar.gz`;
196	    const parent = dir.replace(/\/[^/]+$/, "") || "/";
197	    const base = dir.replace(/^.*\//, "");
198	    const script =
199	      `mkdir -p ${shq(GAME_BACKUP_DIR)} && ` +
200	      `tar czf ${shq(archive)} -C ${shq(parent)} ${shq(base)} 2>&1 && ` +
201	      `stat -c '%s' ${shq(archive)}`;
202	    const r = await exec(conn, script, SETUP_TIMEOUT_MS);
203	    if (r.code !== 0) return { ok: false, msg: (r.stderr || r.stdout).trim().slice(0, 200) || "tar failed" };
204	    const size = Number(r.stdout.trim().split(/\r?\n/).pop());
205	    return { ok: true, archive, size: Number.isFinite(size) ? size : 0 };
206	  });
207	
208	  if (!outcome.ok) {
209	    await notify(server.userId, `World backup failed on ${server.hostname}`, outcome.msg, href);
210	    throw new Error(`game backup failed: ${outcome.msg}`);
211	  }
212	  const mb = ((outcome.size ?? 0) / (1024 * 1024)).toFixed(1);
213	  await notify(
214	    server.userId,
215	    `${spec.label} world backup ready on ${server.hostname}`,
216	    `Backed up your world (${mb} MB). Download it from the Manage → Worlds tab.`,
217	    href
218	  );
219	}
