221	/**
222	 * Fire due scheduled tasks. Selects enabled GameSchedule rows whose `nextRunAt`
223	 * has passed. For kind="restart", enqueues a GAME_POWER restart; for kind="command",
224	 * sends an RCON command directly. Advances `nextRunAt` appropriately (daily or
225	 * interval-based). Idempotent / safe on a timer.
226	 */
227	export async function gameScheduleSweep(): Promise<void> {
228	  const now = new Date();
229	  const due = await db.gameSchedule.findMany({
230	    where: { enabled: true, nextRunAt: { lte: now } },
231	    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } } } },
232	    take: 100,
233	  });
234	  if (due.length === 0) return;
235	
236	  for (const s of due) {
237	    // Always advance the clock first so a server that is down / mid-operation does
238	    // not cause the same row to be reselected every tick.
239	    const nextRunAt = s.intervalMinutes
240	      ? computeNextIntervalRun(s.intervalMinutes, now)
241	      : computeNextRun(s.hour, s.minute, now);
242	    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});
243	
244	    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
245	    if (!isGameFamily(fam)) continue;
246	    if (s.server.status !== "RUNNING") continue;
247	
248	    if (s.kind === "command" && s.command) {
249	      // Send RCON command directly (e.g. save-all, weather clear).
250	      const spec = controlSpec(fam);
251	      if (!spec || spec.rcon === "none") continue;
252	      // Load full server for SSH access.
253	      const server = await db.server.findUnique({ where: { id: s.server.id }, select: CONTROL_FIELDS });
254	      if (!server) continue;
255	      try {
256	        await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, s.command!));
257	      } catch {
258	        // Best-effort: command schedules silently skip on failure.
259	      }
260	    } else {
261	      // Restart schedule: check for busy jobs first.
262	      const busy = await db.job.count({
263	        where: {
264	          serverId: s.server.id,
265	          status: { in: ["QUEUED", "RUNNING"] },
266	          type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
267	        },
268	      });
269	      if (busy > 0) continue;
270	
271	      await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
272	    }
273	  }
274	}
