276	/**
277	 * Track player join/leave events by comparing the live RCON player list against
278	 * open PlayerSession rows (leftAt IS NULL). Runs every ~60s from the main loop.
279	 *
280	 * For each RUNNING game server with a gamePlan:
281	 *   - NEW players (in RCON but no open session) → create a PlayerSession
282	 *   - DEPARTED players (open session but not in RCON) → set leftAt = now()
283	 *   - STILL ONLINE → no-op
284	 *
285	 * Per-server try/catch so one unreachable VM never blocks the sweep.
286	 */
287	export async function playerTrackingSweep(): Promise<void> {
288	  if (SANDBOX) return;
289	
290	  const servers = await db.server.findMany({
291	    where: { status: "RUNNING", gamePlanId: { not: null } },
292	    select: CONTROL_FIELDS,
293	  });
294	
295	  const now = new Date();
296	
297	  for (const server of servers) {
298	    try {
299	      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
300	      if (!isGameFamily(fam)) continue;
301	      const spec = controlSpec(fam);
302	      if (!spec || spec.rcon !== "source" || !spec.listCommand) continue;
303	
304	      // Get online players via RCON
305	      const res = await withServerSsh(server as SftpServer, (conn) =>
306	        runRcon(conn, spec, spec.listCommand!)
307	      );
308	      if (!res.ok) continue;
309	      const { players: onlinePlayers } = parsePlayers(spec.family, res.response);
310	      const onlineNames = new Set(onlinePlayers.map((p) => p.name.toLowerCase()));
311	
312	      // Get open sessions for this server
313	      const openSessions = await db.playerSession.findMany({
314	        where: { serverId: server.id, leftAt: null },
315	      });
316	      const sessionByName = new Map(
317	        openSessions.map((s) => [s.playerName.toLowerCase(), s])
318	      );
319	
320	      // NEW players: in RCON but no open session
321	      for (const p of onlinePlayers) {
322	        if (!sessionByName.has(p.name.toLowerCase())) {
323	          await db.playerSession.create({
324	            data: { serverId: server.id, playerName: p.name },
325	          });
326	        }
327	      }
328	
329	      // DEPARTED players: open session but not in RCON
330	      for (const session of openSessions) {
331	        if (!onlineNames.has(session.playerName.toLowerCase())) {
332	          await db.playerSession.update({
333	            where: { id: session.id },
334	            data: { leftAt: now },
335	          });
336	        }
337	      }
338	    } catch (e) {
339	      // Per-server: one failure must not break the sweep
340	      console.error(`[player-tracking] sweep failed for server ${server.id}`, e);
341	    }
342	  }
343	}
