51	     where it sat below three other panels and off the fold. It is a workflow —
52	     describe, Claude plans, you approve, we run it — not a widget. */
53	  { key: "build",     label: "Build with AI",   icon: "sparkles", badge: "AI" },
54	  { key: "settings",  label: "Settings",        icon: "gear" },
55	  { key: "activity",  label: "Activity",        icon: "activity" },
