248	}) {
249	  return (
250	    <div className="flex w-fit gap-1 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1">
251	      {items.map((i) => (
252	        <button
253	          key={i.key}
254	          type="button"
