55	function OnlinePlayers({ serverId, running, playersMax }: { serverId: string; running: boolean; playersMax: number | null }) {
56	  const [players, setPlayers] = useState<Player[] | null>(null);
57	  // Distinct from `players === null`: a failed fetch also leaves `players`
58	  // null (nothing to show), but must not keep rendering "Loading…" forever —
59	  // found live 2026-09-05 via a customer ticket where a broken RCON path
60	  // (lib/game-control.ts) left this panel spinning indefinitely instead of
61	  // surfacing the `err` message already being set correctly below.
62	  const [loaded, setLoaded] = useState(false);
63	  const [supported, setSupported] = useState(true);
64	  const [err, setErr] = useState<string | null>(null);
65	  const [msg, setMsg] = useState<string | null>(null);
66	  const [pending, start] = useTransition();
67	
68	  const refresh = useCallback(() => {
69	    start(async () => {
70	      const r = await getGamePlayers(serverId);
71	      if (r.ok) { setPlayers(r.players); setErr(null); }
72	      else { setErr(r.error); if (/not available/i.test(r.error)) setSupported(false); }
73	      setLoaded(true);
74	    });
75	  }, [serverId]);
76	
77	  useEffect(() => { if (running) refresh(); }, [running, refresh]);
78	
79	  function act(kind: "kick" | "ban", id: string) {
80	    if (kind === "ban" && !window.confirm(`Ban ${id}? They will be disconnected and blocked.`)) return;
81	    setMsg(null);
82	    start(async () => {
83	      const r = kind === "kick" ? await kickPlayer(serverId, id) : await banPlayer(serverId, id);
84	      if (!r.ok) setErr(r.error); else { setMsg(`${kind === "kick" ? "Kicked" : "Banned"} ${id}`); refresh(); }
85	    });
86	  }
87	
88	  function doGamemode(name: string, mode: string) {
89	    setMsg(null);
90	    start(async () => {
91	      const r = await setPlayerGameMode(serverId, name, mode);
