1364	      }),
1365	    ]);
1366	
1367	    const playerMap = new Map<string, { totalMs: number; sessions: number }>();
1368	    let totalPlaytimeMs = 0;
1369	    let completedSessions = 0;
1370	
1371	    for (const s of allSessions) {
1372	      const ms = s.leftAt
1373	        ? s.leftAt.getTime() - s.joinedAt.getTime()
1374	        : Date.now() - s.joinedAt.getTime();
1375	      totalPlaytimeMs += ms;
1376	      if (s.leftAt) completedSessions++;
1377	
1378	      const key = s.playerName.toLowerCase();
1379	      const existing = playerMap.get(key) ?? { totalMs: 0, sessions: 0 };
1380	      existing.totalMs += ms;
