model AdsConversion {
  id           String    @id @default(cuid())
  dedupeKey    String    @unique // e.g. "signup:<userId>" / "purchase:<orderId>" — never upload twice
  kind         String // signup | purchase | vps | hosting | game | email
  userId       String?
  gclid        String
  valueCents   Int?
  currency     String    @default("USD")
  status       String    @default("PENDING") // PENDING | UPLOADED | FAILED | SKIPPED
  error        String?
  conversionAt DateTime  @default(now())
  uploadedAt   DateTime?

  @@index([status])
}

// ---------------------------------------------------------------------------
// Player session tracking (game servers). Rows created/updated by a periodic
// worker sweep that polls RCON `list` on running game servers: a new row on
// first-seen, `leftAt` stamped when a player disappears from the list.
// ---------------------------------------------------------------------------
model PlayerSession {
  id         String    @id @default(cuid())
  serverId   String
  server     Server    @relation(fields: [serverId], references: [id], onDelete: Cascade)
  playerName String
  joinedAt   DateTime  @default(now())
  leftAt     DateTime?

  @@index([serverId, joinedAt])
  @@index([serverId, playerName])
}

