// ---------------------------------------------------------------------------
// Log-derived player tracking for game families with NO remote console (e.g.
// Valheim's dedicated server: no native RCON, only a container log). RCON's
// playerTrackingSweep can't run for these, so logPlayerTrackingSweep tails the
// service's own log instead (readGameLogs, already used by the Console tab) and
// writes real PlayerSession rows — the existing history/stats UI needs no
// changes to work for these families too.
//
// One row per server. `lastLine` is the last raw log line already processed, so
// the next tail is diffed against it and lines are never double-counted (and,
// on the very first sweep for a server, nothing is back-filled as a "join" —
// there is no way to know when an already-connected player actually joined).
// `onlineCount` is ground truth, read straight off the log's own running
// headcount line. `onlineNames` is a best-effort FIFO of who the sweep BELIEVES
// is still connected: joins are observed and named directly, but a disconnect
// in these logs never names who left (only the new count) — see
// logPlayerTrackingSweep's doc comment in worker/game-control.ts for exactly how
// that gap is handled, and why it's a documented limitation, not a bug.
// ---------------------------------------------------------------------------
model GameLogCursor {
  id          String   @id @default(cuid())
  serverId    String   @unique
  server      Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  lastLine    String?  @db.Text
  onlineNames Json     @default("[]") // string[] of believed-online player names, oldest-join first
  onlineCount Int      @default(0)
  updatedAt   DateTime @updatedAt
}

// ---------------------------------------------------------------------------
// Log-derived player tracking (families with rcon === "none")
// ---------------------------------------------------------------------------

export type LogTrackingSpec = {
  /** Matches a join line; capture group 1 is the player's display name. */
  joinRe: RegExp;
  /**
   * Matches the server's own running connection-count line; capture group 1
   * is the new total online count. This number is GROUND TRUTH straight off
   * the game's own log — unlike `joinRe`, nothing about it is inferred.
   */
  countRe: RegExp;
};

/**
 * Families with NO remote console (`rcon: "none"` above) but a real,
 * parseable join/headcount signal in their own log — tailed read-only via the
 * same `readGameLogs` the Console tab already uses, never a new SSH surface.
 *
 * valheim: verified against the `lloesche/valheim-server` Docker image (the
 * platform's real Valheim template) 2026-09-20 — a join logs
 * `Got character ZDOID from <name> : <id>`, and the server's own connection
 * bookkeeping logs `... now N player(s)` on every disconnect. The join line
 * names the joiner; the disconnect line does NOT name the leaver, only the new
 * total — see worker/game-control.ts's `logPlayerTrackingSweep` doc comment
 * for exactly how that gap is handled (inference, not observation, and always
 * labeled as such).
 */
export const GAME_LOG_TRACKING: Partial<Record<GameFamily, LogTrackingSpec>> = {
  valheim: {
    joinRe: /Got character ZDOID from (.+?) : /,
    countRe: /now (\d+) player\(s\)/i,
  },
};

export function logTrackingSpec(family: string | null | undefined): LogTrackingSpec | null {
  if (!family) return null;
  return (GAME_LOG_TRACKING as Record<string, LogTrackingSpec>)[family] ?? null;
}

