/** Close the oldest still-open PlayerSession for `playerName` on `serverId`. */
async function closeOpenLogSession(serverId: string, playerName: string, inferred: boolean): Promise<void> {
  const open = await db.playerSession.findFirst({
    where: { serverId, playerName: { equals: playerName, mode: "insensitive" }, leftAt: null },
    orderBy: { joinedAt: "asc" },
  });
  if (open) {
    await db.playerSession.update({ where: { id: open.id }, data: { leftAt: new Date(), leftAtInferred: inferred } });
  }
}

/**
 * Track player join/leave for game families with NO remote console (Valheim
 * today, via GAME_LOG_TRACKING in lib/game-control.ts) by tailing their own log
 * instead of RCON — `readGameLogs`, the exact same read-only path the Console
 * tab already uses. Runs every ~60s from the main loop, ALONGSIDE (not instead
 * of) `playerTrackingSweep` above — a server only ever matches one of the two,
 * since `logTrackingSpec` is only registered for families with `rcon: "none"`.
 *
 * THE REAL LIMITATION — read this before changing the inference below. Valheim's
 * dedicated-server log names a player on JOIN
 * (`Got character ZDOID from <name> : <id>`) but NOT on disconnect — a
 * disconnect only ever updates a running headcount (`... now N player(s)`). So
 * when the count drops we know FOR CERTAIN that one fewer player is connected,
 * but NOT which one. This sweep's handling of that gap:
 *
 *   - `onlineCount` always tracks the log's own headcount line exactly —
 *     ground truth, never guessed.
 *   - `onlineNames` (persisted on GameLogCursor) is a FIFO of names in join
 *     order. On a headcount decrement, the OLDEST believed-online name is
 *     popped and ITS PlayerSession is closed with `leftAtInferred: true` — a
 *     guess, not an observation, and wrong whenever the player who actually
 *     left isn't the longest-connected one of the group. `leftAtInferred` is
 *     surfaced in the UI (GamePlayerHistory) so this is never presented as
 *     fact.
 *   - If the count hits exactly 0, every remaining open session for the
 *     server is closed — that IS certain (nobody is connected), so those are
 *     NOT marked inferred.
 *   - If a JOIN names someone the FIFO still believes is online (drift from an
 *     earlier wrong guess), that stale session is closed first (inferred)
 *     before the fresh one opens, so drift self-corrects instead of piling up.
 *   - A count INCREASE with no matching join line parsed in this batch is left
 *     alone rather than inventing a name — `onlineCount` still updates.
 *
 * Incremental tailing: `GameLogCursor.lastLine` is the last raw line this sweep
 * already processed; each run only walks lines after that mark in the new tail.
 * `readGameLogs` is capped at the last 500 lines (lib/game-control.ts), so a
 * server producing >500 log lines between two ~60s sweeps could skip events —
 * acceptable for Valheim's actual join/leave volume, but worth knowing if this
 * pattern is reused for a chattier log. If the previous marker line has rolled
 * completely out of the new tail, this run processes nothing (rather than risk
 * double-counting) and just re-marks the newest line. On a server's very first
 * sweep (no GameLogCursor row yet) nothing is back-filled as a join — there is
 * no way to know when an already-connected player actually joined — so the
 * cursor is seeded silently and tracking starts clean from the next line on.
 */
export async function logPlayerTrackingSweep(): Promise<void> {
  if (SANDBOX) return;

  const servers = await db.server.findMany({
    where: { status: "RUNNING", gamePlanId: { not: null } },
    select: CONTROL_FIELDS,
  });

  for (const server of servers) {
    try {
      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
      if (!isGameFamily(fam)) continue;
      const spec = controlSpec(fam);
      const tracking = logTrackingSpec(fam);
      if (!spec || !tracking) continue; // only families with a registered log-tracking spec

      const logRes = await withServerSsh(server as SftpServer, (conn) => readGameLogs(conn, spec, 500));
      if (!logRes.ok) continue;
      const lines = logRes.lines;
      if (lines.length === 0) continue;

      const cursor = await db.gameLogCursor.findUnique({ where: { serverId: server.id } });
      const isFirstSweep = !cursor;

      let startIdx = lines.length; // default: process nothing (marker missing/rolled out)
      if (isFirstSweep) {
        startIdx = lines.length; // seed only — no back-fill, see doc comment
      } else if (cursor!.lastLine == null) {
        startIdx = 0; // a cursor existed but had no marker yet (shouldn't normally happen)
      } else {
        const idx = lines.lastIndexOf(cursor!.lastLine);
        startIdx = idx >= 0 ? idx + 1 : lines.length;
      }

      let onlineNames: string[] = Array.isArray(cursor?.onlineNames) ? [...(cursor!.onlineNames as unknown as string[])] : [];
      let onlineCount = cursor?.onlineCount ?? 0;

      for (let i = startIdx; i < lines.length; i++) {
        const line = lines[i];

        const joinM = tracking.joinRe.exec(line);
        if (joinM) {
          const name = joinM[1].trim();
          if (name) {
            const dupIdx = onlineNames.findIndex((n) => n.toLowerCase() === name.toLowerCase());
            if (dupIdx >= 0) {
              // FIFO drift: we thought they were already online. Close the
              // stale (inferred) session before opening the real new one.
              onlineNames.splice(dupIdx, 1);
              await closeOpenLogSession(server.id, name, true);
            }
            onlineNames.push(name);
            await db.playerSession.create({ data: { serverId: server.id, playerName: name } });
          }
          continue;
        }

        const countM = tracking.countRe.exec(line);
        if (countM) {
          const newCount = Number(countM[1]);
          if (Number.isFinite(newCount) && newCount !== onlineCount) {
            if (newCount === 0) {
              await db.playerSession.updateMany({
                where: { serverId: server.id, leftAt: null },
                data: { leftAt: new Date(), leftAtInferred: false },
              });
              onlineNames = [];
            } else if (newCount < onlineCount) {
              const drop = onlineCount - newCount;
              for (let d = 0; d < drop && onlineNames.length > 0; d++) {
                const leaver = onlineNames.shift()!;
                await closeOpenLogSession(server.id, leaver, true);
              }
            }
            onlineCount = newCount;
          }
        }
      }

      const lastLine = lines[lines.length - 1];
      await db.gameLogCursor.upsert({
        where: { serverId: server.id },
        create: { serverId: server.id, lastLine, onlineNames, onlineCount },
        update: { lastLine, onlineNames, onlineCount },
      });
    } catch (e) {
      console.error(`[log-player-tracking] sweep failed for server ${server.id}`, e);
    }
  }
}

