export type PlayerSessionRow = {
  id: string;
  playerName: string;
  joinedAt: string;
  leftAt: string | null;
  durationMs: number | null;
  // True when `leftAt` is a best-effort GUESS (log-only families like Valheim,
  // where a disconnect never names who left — see logPlayerTrackingSweep in
  // worker/game-control.ts), not something actually observed. Always false for
  // RCON-tracked families.
  leftAtInferred: boolean;
};

// ---------------------------------------------------------------------------
// Log-derived player status (families with no remote console, e.g. Valheim)
// ---------------------------------------------------------------------------

export type LogPlayerStatusResult =
  | {
      ok: true;
      /** Ground truth — read straight off the log's own headcount line. */
      onlineCount: number;
      /** When that headcount was last confirmed (freshness of `onlineCount`). */
      countUpdatedAt: string | null;
      /** Best-effort "believed still connected" names (see doc comment below). */
      online: { name: string; lastJoinedAt: string }[];
      /** Every player ever seen, most-recently-active first. */
      known: { name: string; online: boolean; lastSeenAt: string }[];
    }
  | { ok: false; error: string };

/**
 * Player visibility for game families with NO remote console (Valheim today).
 * Backed by `logPlayerTrackingSweep` (worker/game-control.ts), which tails the
 * server's own log and writes real PlayerSession rows — so `onlineCount` and
 * `countUpdatedAt` are ground truth (straight off the log's headcount line),
 * while `online`/`known[].online` are the sweep's BEST-EFFORT belief about who
 * that count refers to, because a disconnect in these logs never names the
 * leaver. Callers should show that distinction, not flatten it away.
 */
export async function getLogPlayerStatus(serverId: string): Promise<LogPlayerStatusResult> {
  try {
    const { server } = await ownedServer(serverId);

    if (SANDBOX) {
      const now = new Date().toISOString();
      const earlier = new Date(Date.now() - 3 * 60 * 60_000).toISOString();
      return {
        ok: true,
        onlineCount: 1,
        countUpdatedAt: now,
        online: [{ name: "Woody", lastJoinedAt: now }],
        known: [
          { name: "Woody", online: true, lastSeenAt: now },
          { name: "Ash", online: false, lastSeenAt: earlier },
        ],
      };
    }

    const [cursor, sessions] = await Promise.all([
      db.gameLogCursor.findUnique({ where: { serverId: server.id } }),
      db.playerSession.findMany({
        where: { serverId: server.id },
        orderBy: { joinedAt: "desc" },
        select: { playerName: true, joinedAt: true, leftAt: true },
        take: 500,
      }),
    ]);

    // First occurrence per (lowercased) name, in desc order, is that player's
    // most recent session — gives an accurate online flag + last-seen time.
    const byPlayer = new Map<string, { name: string; lastJoinedAt: Date; online: boolean }>();
    for (const s of sessions) {
      const key = s.playerName.toLowerCase();
      if (!byPlayer.has(key)) byPlayer.set(key, { name: s.playerName, lastJoinedAt: s.joinedAt, online: s.leftAt === null });
    }
    const known = [...byPlayer.values()]
      .sort((a, b) => b.lastJoinedAt.getTime() - a.lastJoinedAt.getTime())
      .map((p) => ({ name: p.name, online: p.online, lastSeenAt: p.lastJoinedAt.toISOString() }));

    return {
      ok: true,
      onlineCount: cursor?.onlineCount ?? known.filter((k) => k.online).length,
      countUpdatedAt: cursor?.updatedAt.toISOString() ?? null,
      online: known.filter((k) => k.online).map((k) => ({ name: k.name, lastJoinedAt: k.lastSeenAt })),
      known,
    };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

