"use client";

import { useCallback, useEffect, useState, useTransition } from "react";
import { getLogPlayerStatus, type LogPlayerStatusResult } from "@/lib/actions-game-control";

/**
 * "Online" view for game families with NO remote console (Valheim today).
 * There is no RCON `list` command to poll, so this reads what
 * `logPlayerTrackingSweep` (worker/game-control.ts) has already derived from
 * tailing the server's own log — a real background poller, not a
 * parse-on-page-load trick, so it also has history between visits.
 *
 * Honesty matters here: the total online COUNT is ground truth (the log's own
 * headcount line), but WHICH names make up that count is the sweep's
 * best-effort belief, because a disconnect in this log never names the
 * leaver — only the join does. The banner below says so; the name list is
 * never presented as a guaranteed-accurate real-time roster.
 */
export function GameLogPlayers({ serverId, running }: { serverId: string; running: boolean }) {
  const [data, setData] = useState<Extract<LogPlayerStatusResult, { ok: true }> | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [loaded, setLoaded] = useState(false);
  const [pending, start] = useTransition();

  const refresh = useCallback(() => {
    start(async () => {
      const r = await getLogPlayerStatus(serverId);
      if (r.ok) { setData(r); setErr(null); } else setErr(r.error);
      setLoaded(true);
    });
  }, [serverId]);

  useEffect(() => {
    refresh();
    // The sweep runs ~every 60s; poll a little slower than that so the panel
    // reflects a fresh row almost every time without hammering the DB.
    const t = setInterval(refresh, 75_000);
    return () => clearInterval(t);
  }, [refresh]);

  return (
    <div className="space-y-4">
      <div className="card">
        <div className="flex items-center justify-between gap-3">
          <div>
            <h3 className="font-semibold">Currently online</h3>
            <p className="mt-0.5 text-sm text-slate-400">
              {running
                ? "This game has no remote console, so this is read from the server's own log instead of a live query."
                : "Start the server to see who's connected."}
            </p>
          </div>
          <button className="text-xs text-slate-400 hover:text-white disabled:opacity-40" onClick={refresh} disabled={pending || !running}>
            Refresh
          </button>
        </div>

        {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}

        {!running ? null : !loaded ? (
          <p className="mt-4 text-sm text-slate-500">Loading…</p>
        ) : data ? (
          <>
            <p className="mt-4 text-2xl font-bold text-emerald-400">
              {data.onlineCount} <span className="text-sm font-medium text-slate-400">online now</span>
            </p>
            {data.countUpdatedAt && (
              <p className="mt-1 text-xs text-slate-500">Count confirmed {relativeTime(data.countUpdatedAt)} from the server log.</p>
            )}

            {/* The honesty caveat: this list can lag or briefly mis-name who's
                online, because the log only ever names a JOIN, never a leave. */}
            {data.onlineCount > 0 && (
              <p className="mt-3 rounded-lg border border-amber-500/20 bg-amber-500/[0.06] px-3 py-2 text-xs leading-relaxed text-amber-200/90">
                The count above is exact. The names below are our best guess at who
                that count refers to — this game&apos;s log tells us when someone
                disconnects, but never who, so the name list can occasionally be a
                step behind (it self-corrects on their next join).
              </p>
            )}

            {data.online.length === 0 ? (
              <p className="mt-4 text-sm text-slate-500">No players connected.</p>
            ) : (
              <ul className="mt-4 divide-y divide-white/[0.06]">
                {data.online.map((p) => (
                  <li key={p.name} className="flex items-center justify-between gap-3 py-2.5">
                    <span className="flex items-center gap-2.5 text-sm">
                      <span className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-brand-500/40 to-accent-blue/30 text-[11px] font-bold text-white">
                        {p.name.slice(0, 2).toUpperCase()}
                      </span>
                      <span className="font-medium text-slate-100">{p.name}</span>
                      <span className="flex items-center gap-1 rounded-full bg-emerald-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-400">
                        <span className="h-2 w-2 rounded-full bg-emerald-400" />
                        Online
                      </span>
                    </span>
                    <span className="text-xs text-slate-500">Joined {relativeTime(p.lastJoinedAt)}</span>
                  </li>
                ))}
              </ul>
            )}
          </>
        ) : null}
      </div>

      <div className="card">
        <h3 className="font-semibold">Known players</h3>
        <p className="mt-0.5 text-sm text-slate-400">Everyone who has connected, with when they were last seen.</p>
        {!loaded || !data ? (
          <p className="mt-4 text-sm text-slate-500">{loaded ? "" : "Loading…"}</p>
        ) : data.known.length === 0 ? (
          <p className="mt-4 text-sm text-slate-500">No players recorded yet. Player activity is tracked automatically while the server runs.</p>
        ) : (
          <ul className="mt-4 divide-y divide-white/[0.06]">
            {data.known.map((p) => (
              <li key={p.name} className="flex items-center justify-between gap-3 py-2.5">
                <span className="flex items-center gap-2.5 text-sm">
                  <span className="flex h-8 w-8 items-center justify-center rounded-full bg-gradient-to-br from-brand-500/40 to-accent-blue/30 text-[11px] font-bold text-white">
                    {p.name.slice(0, 2).toUpperCase()}
                  </span>
                  <span className="font-medium text-slate-100">{p.name}</span>
                  <span
                    className={
                      "rounded-full px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide " +
                      (p.online ? "bg-emerald-500/10 text-emerald-400" : "bg-white/[0.06] text-slate-400")
                    }
                  >
                    {p.online ? "Online" : "Offline"}
                  </span>
                </span>
                <span className="text-xs text-slate-500">
                  {p.online ? "Since" : "Last seen"} {relativeTime(p.lastSeenAt)}
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

function relativeTime(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  if (diff < 60_000) return "just now";
  const min = Math.floor(diff / 60_000);
  if (min < 60) return `${min}m ago`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr}h ago`;
  const d = Math.floor(hr / 24);
  return `${d}d ago`;
}

